import csv
from datetime import datetime
from typing import Any

import geojson

from src.security.project_scan import assert_project_writable
from src.utils.logging_utils import get_logger

logger = get_logger(__name__)


class ResultExporter:
    """Exports localization results to various formats (CSV, GeoJSON, KML)."""

    @staticmethod
    def export_csv(results: list[dict[str, Any]], output_path: str) -> None:
        """Exports localization results to a CSV file."""
        if not results:
            logger.warning("No results to export")
            return
        # Protection against writing results into an encrypted project.
        assert_project_writable(output_path)

        fieldnames = [
            "frame_id",
            "timestamp",
            "lat",
            "lon",
            "confidence",
            "matched_frame",
            "inliers",
        ]
        if any(r.get("coordinate_kind") == "local_planar" for r in results):
            if all(r.get("coordinate_kind") == "local_planar" for r in results):
                fieldnames = [k for k in fieldnames if k not in ("lat", "lon")]
            fieldnames += ["x", "y", "coordinate_kind", "coordinate_units"]
        if any("fix_source" in r for r in results):
            # keyframe / optical_flow / dead_reckoning (not confirmed by the map)
            fieldnames.append("fix_source")

        with open(output_path, "w", newline="", encoding="utf-8") as f:
            writer = csv.DictWriter(f, fieldnames=fieldnames, extrasaction="ignore")
            writer.writeheader()
            for row in results:
                row = dict(row)
                if row.get("coordinate_kind") == "local_planar":
                    row.pop("lat", None)
                    row.pop("lon", None)
                writer.writerow(row)

        logger.success(f"Exported {len(results)} results to CSV: {output_path}")

    @staticmethod
    def export_geojson(results: list[dict[str, Any]], output_path: str) -> None:
        """Exports localization results to GeoJSON format including FOV polygons."""
        if any(r.get("coordinate_kind") == "local_planar" for r in results):
            raise ValueError("Local maps have no GPS coordinates. Export as CSV instead.")
        assert_project_writable(output_path)
        features = []
        for r in results:
            if "lat" not in r or "lon" not in r:
                continue

            # 1. Point feature (trajectory)
            point = geojson.Feature(
                geometry=geojson.Point((r["lon"], r["lat"])),
                properties={
                    "type": "trajectory_point",
                    "frame_id": r.get("frame_id"),
                    "confidence": r.get("confidence"),
                    "timestamp": r.get("timestamp"),
                    "matched_frame": r.get("matched_frame"),
                    "fix_source": r.get("fix_source", "keyframe"),
                },
            )
            features.append(point)

            # 2. Polygon feature (FOV) - if available
            fov = r.get("fov_polygon")
            if fov and len(fov) >= 3:
                # GeoJSON Polygon coordinates must be a list of rings,
                # each ring is a list of [lon, lat] points, first and last must be same.
                coords = [[lon, lat] for lat, lon in fov]
                # Close the polygon
                if coords[0] != coords[-1]:
                    coords.append(coords[0])

                polygon = geojson.Feature(
                    geometry=geojson.Polygon([coords]),
                    properties={
                        "type": "fov_polygon",
                        "frame_id": r.get("frame_id"),
                        "confidence": r.get("confidence"),
                    },
                )
                features.append(polygon)

        feature_collection = geojson.FeatureCollection(
            features, properties={"exported_at": datetime.now().isoformat()}
        )

        with open(output_path, "w", encoding="utf-8") as f:
            geojson.dump(feature_collection, f, indent=2, ensure_ascii=False)

        logger.success(f"Exported {len(features)} features to GeoJSON: {output_path}")

    @staticmethod
    def export_kml(
        results: list[dict[str, Any]], output_path: str, name: str = "Drone Track"
    ) -> None:
        """Exports localization trajectory and points to KML (Google Earth)."""
        if any(r.get("coordinate_kind") == "local_planar" for r in results):
            raise ValueError("Local maps have no GPS coordinates. Export as CSV instead.")
        assert_project_writable(output_path)
        lines = [
            '<?xml version="1.0" encoding="UTF-8"?>',
            '<kml xmlns="http://www.opengis.net/kml/2.2">',
            "<Document>",
            f"  <name>{name}</name>",
            f"  <description>Exported {datetime.now().strftime('%Y-%m-%d %H:%M')}</description>",
        ]

        # Marker style
        lines.extend(
            [
                '  <Style id="dronePoint">',
                "    <IconStyle>",
                "      <scale>0.6</scale>",
                "      <Icon><href>http://maps.google.com/mapfiles/kml/shapes/airports.png</href></Icon>",
                "    </IconStyle>",
                "  </Style>",
            ]
        )

        # Points
        for r in results:
            if "lat" not in r or "lon" not in r:
                continue
            conf = r.get("confidence", 0)
            fid = r.get("frame_id", "?")
            lines.extend(
                [
                    "  <Placemark>",
                    f"    <name>Frame {fid}</name>",
                    f"    <description>Confidence: {conf:.2f}</description>",
                    "    <styleUrl>#dronePoint</styleUrl>",
                    "    <Point>",
                    f"      <coordinates>{r['lon']},{r['lat']},0</coordinates>",
                    "    </Point>",
                    "  </Placemark>",
                ]
            )

        # Track line
        coords_str = " ".join(
            f"{r['lon']},{r['lat']},0" for r in results if "lat" in r and "lon" in r
        )
        if coords_str:
            lines.extend(
                [
                    "  <Placemark>",
                    f"    <name>{name} - Path</name>",
                    "    <Style><LineStyle><color>ff0000ff</color><width>3</width></LineStyle></Style>",
                    "    <LineString>",
                    "      <tessellate>1</tessellate>",
                    f"      <coordinates>{coords_str}</coordinates>",
                    "    </LineString>",
                    "  </Placemark>",
                ]
            )

        lines.extend(["</Document>", "</kml>"])

        with open(output_path, "w", encoding="utf-8") as f:
            f.write("\n".join(lines))

        logger.success(f"Exported {len(results)} points to KML: {output_path}")

    @staticmethod
    def export_objects_csv(results: list[dict[str, Any]], output_path: str) -> None:
        """Exports tracked objects to a CSV file."""
        if not results:
            return
        assert_project_writable(output_path)
        fieldnames = ["track_id", "class_name", "timestamp", "lat", "lon", "confidence"]
        if any(r.get("coordinate_kind") == "local_planar" for r in results):
            if all(r.get("coordinate_kind") == "local_planar" for r in results):
                fieldnames = [k for k in fieldnames if k not in ("lat", "lon")]
            fieldnames += ["x", "y", "coordinate_kind", "coordinate_units"]
        if any("fix_source" in r for r in results):
            # keyframe / optical_flow / dead_reckoning (not confirmed by the map)
            fieldnames.append("fix_source")
        with open(output_path, "w", newline="", encoding="utf-8") as f:
            writer = csv.DictWriter(f, fieldnames=fieldnames, extrasaction="ignore")
            writer.writeheader()
            for row in results:
                row = dict(row)
                if row.get("coordinate_kind") == "local_planar":
                    row.pop("lat", None)
                    row.pop("lon", None)
                writer.writerow(row)
        logger.success(f"Exported {len(results)} objects to CSV: {output_path}")

    @staticmethod
    def export_objects_geojson(results: list[dict[str, Any]], output_path: str) -> None:
        """Exports tracked objects to GeoJSON format."""
        if any(r.get("coordinate_kind") == "local_planar" for r in results):
            raise ValueError("Local maps have no GPS coordinates. Export as CSV instead.")
        if not results:
            return
        assert_project_writable(output_path)
        features = []
        for r in results:
            if "lat" not in r or "lon" not in r:
                continue
            point = geojson.Feature(
                geometry=geojson.Point((r["lon"], r["lat"])),
                properties={
                    "type": "object_point",
                    "track_id": r.get("track_id"),
                    "class_name": r.get("class_name"),
                    "confidence": r.get("confidence"),
                    "timestamp": r.get("timestamp"),
                },
            )
            features.append(point)

        feature_collection = geojson.FeatureCollection(
            features, properties={"exported_at": datetime.now().isoformat()}
        )
        with open(output_path, "w", encoding="utf-8") as f:
            geojson.dump(feature_collection, f, indent=2, ensure_ascii=False)
        logger.success(f"Exported {len(features)} objects to GeoJSON: {output_path}")


