import cv2
import numpy as np

from src.utils.logging_utils import get_logger

logger = get_logger(__name__)

# PoseLib: LO-RANSAC with 4-point solver (outperforms MAGSAC++ on small datasets)
try:
    import poselib

    _POSELIB_AVAILABLE = True
    logger.info(f"PoseLib {poselib.__version__} available — LO-RANSAC enabled")
except ImportError:
    _POSELIB_AVAILABLE = False
    logger.info("PoseLib not installed — using OpenCV MAGSAC++ for homography estimation")


class GeometryTransforms:
    """Geometric transformations for localization with robust estimation (MAGSAC++)"""

    @staticmethod
    def is_matrix_valid(
        M: np.ndarray,
        is_homography: bool = False,
        min_scale: float = 0.001,
        max_scale: float = 100.0,
        max_shear: float = 0.8,
    ) -> bool:
        """
        Check if the transformation matrix is physically realistic for drone imagery.

        Args:
            M: Transformation matrix (2x3 for Affine or 3x3 for Homography)
            is_homography: True if M is a 3x3 Homography matrix
            min_scale: Minimum allowed scale factor
            max_scale: Maximum allowed scale factor
            max_shear: Maximum allowed shear (dot product of normalized basis vectors)
        """
        if M is None:
            return False

        try:
            if is_homography:
                # For Homography, we care about the affine part for stability checks
                if M.shape != (3, 3):
                    return False
                # Normalize by M[2,2] if possible
                if abs(M[2, 2]) < 1e-9:
                    return False
                M = M / M[2, 2]

                # Check perspective components (drone camera can tilt, so allow up to 0.02)
                # If these are very large, the corners will fly off to infinity
                if abs(M[2, 0]) > 0.02 or abs(M[2, 1]) > 0.02:
                    logger.debug(
                        f"Matrix invalid: Extreme perspective warp ({M[2, 0]:.5f}, {M[2, 1]:.5f})"
                    )
                    return False

                A = M[:2, :2]
                det = np.linalg.det(A)
            else:
                if M.shape != (2, 3):
                    return False
                A = M[:2, :2]
                det = np.linalg.det(A)

            # 1. Determinant must be non-zero (prevent degenerate matrices)
            if abs(det) < 1e-9:
                logger.debug(
                    f"Matrix invalid: Degenerate matrix with determinant near zero ({det})"
                )
                return False
            # Allow negative determinant since mapping Image Y (down) to Map Y (up) requires reflection!

            # 2. Extract scale and shear from basis vectors
            u = A[:, 0]
            v = A[:, 1]
            scale_u = np.linalg.norm(u)
            scale_v = np.linalg.norm(v)

            # Check scale bounds (drone altitude/zoom sanity)
            if not (min_scale < scale_u < max_scale and min_scale < scale_v < max_scale):
                logger.debug(f"Matrix invalid: Scale out of bounds ({scale_u:.2f}, {scale_v:.2f})")
                return False

            # 3. Check Aspect Ratio (should be close to 1.0 for drone imagery)
            # Expand anisotropy bounds for fast forward flight with camera tilt
            aspect_ratio = scale_u / (scale_v + 1e-9)
            if not (0.5 < aspect_ratio < 2.0):
                logger.debug(
                    f"Matrix invalid: Extreme aspect ratio distortion ({aspect_ratio:.2f})"
                )
                return False

            # 4. Check Shear (cos of angle between basis vectors)
            # Drone mapping shouldn't have extreme shear. Reject if vectors are not ~orthogonal.
            shear = abs(np.dot(u, v) / (scale_u * scale_v + 1e-9))
            if shear > max_shear:
                logger.debug(f"Matrix invalid: Extreme shear detected ({shear:.2f} > {max_shear})")
                return False

            # 5. Check Rotation Stability
            return True

        except Exception as e:
            logger.error(
                f"Error during matrix validation: {e} | "
                f"matrix_shape={M.shape if M is not None else None}, "
                f"is_homography={is_homography}",
                exc_info=True,
            )
            return False

    @staticmethod
    def reprojection_errors(src_pts: np.ndarray, dst_pts: np.ndarray, H: np.ndarray) -> np.ndarray:
        """Reprojection errors ``|H·src − dst|`` for each match, shape (N,)."""
        pts_transformed = GeometryTransforms.apply_homography(src_pts, H)
        return np.sqrt(np.sum((pts_transformed - dst_pts) ** 2, axis=1))

    @staticmethod
    def compute_mad_threshold(
        src_pts: np.ndarray,
        dst_pts: np.ndarray,
        H: np.ndarray,
        k: float = 2.5,
        min_threshold: float = 1.0,
        inlier_mask: np.ndarray | None = None,
    ) -> float:
        """MAD-RANSAC: adaptive threshold based on median absolute deviation of reprojection errors.

        Instead of a fixed threshold (e.g. 3.0 px), computes threshold from error distribution:
            threshold = median(errors) + k * 1.4826 * MAD(errors)

        Args:
            src_pts: Source points (N, 2)
            dst_pts: Destination points (N, 2)
            H: Precomputed homography matrix (3x3)
            k: Sensitivity coefficient (higher -> softer threshold)
            min_threshold: Minimum threshold (px)
            inlier_mask: Boolean mask (N,) of RANSAC inliers. ``None`` uses all points.

        Returns:
            Adaptive reprojection threshold (px)
        """
        errors = GeometryTransforms.reprojection_errors(src_pts, dst_pts, H)
        if inlier_mask is not None:
            sel = np.asarray(inlier_mask).ravel().astype(bool)
            if sel.any():
                errors = errors[sel]
        median_err = np.median(errors)
        mad = np.median(np.abs(errors - median_err))
        # 1.4826 is the MAD normalization constant for normal distributions
        threshold = median_err + k * 1.4826 * mad
        return max(threshold, min_threshold)

    # Minimum points for homography estimation
    _MIN_HOMOGRAPHY_PTS = 4

    @staticmethod
    def _refine_mask_mad(
        src_pts: np.ndarray,
        dst_pts: np.ndarray,
        H: np.ndarray,
        mask: np.ndarray | None,
        k: float,
        ransac_threshold: float,
    ) -> np.ndarray | None:
        """Tightens inlier mask using adaptive MAD threshold.

        Key property: mask can only shrink. Adaptive MAD threshold is calculated
        exclusively over RANSAC inliers to filter out remaining noisy points.
        """
        if mask is None or H is None:
            return mask

        base = np.asarray(mask).ravel().astype(bool)
        n_base = int(base.sum())
        if n_base < GeometryTransforms._MIN_HOMOGRAPHY_PTS:
            return mask

        raw_mad_threshold = GeometryTransforms.compute_mad_threshold(
            src_pts, dst_pts, H, k=k, inlier_mask=base
        )
        # MAD is a refinement of the estimator's acceptance region.  It must
        # never relax that region: a bad model can have a very large residual
        # median even among the points marked by USAC/PoseLib, which previously
        # produced thresholds in the hundreds of pixels.  The mask still could
        # not grow, but those bad points survived and looked like a strong fit.
        mad_threshold = min(float(ransac_threshold), float(raw_mad_threshold))
        errors = GeometryTransforms.reprojection_errors(src_pts, dst_pts, H)
        refined = base & (errors < mad_threshold)
        n_ref = int(refined.sum())

        if n_ref < GeometryTransforms._MIN_HOMOGRAPHY_PTS:
            logger.debug(
                f"MAD-RANSAC: refinement left {n_ref} points "
                f"(< {GeometryTransforms._MIN_HOMOGRAPHY_PTS}) — keeping RANSAC mask"
            )
            return mask

        logger.debug(
            f"MAD-RANSAC: initial_thresh={ransac_threshold:.1f} -> "
            f"adaptive_thresh={mad_threshold:.2f} px "
            f"(raw_mad={raw_mad_threshold:.2f}), "
            f"inliers={n_ref}/{n_base} (out of {len(base)} matches)"
        )
        return refined.astype(np.uint8).reshape(-1, 1)

    @staticmethod
    def estimate_homography(
        src_pts: np.ndarray,
        dst_pts: np.ndarray,
        ransac_threshold: float = 3.0,
        max_iters: int = 2000,
        confidence: float = 0.99,
        fallback_to_affine: bool = True,
        backend: str = "opencv",
        use_mad_ransac: bool = False,
        mad_k_factor: float = 2.5,
        frame_size: tuple[int, int] | None = None,
    ):
        """
        Estimate Homography with configurable backend.

        Args:
            backend: "poselib" (LO-RANSAC) or "opencv" (MAGSAC++, default)
        """
        if len(src_pts) < 4:
            logger.debug(
                f"Cannot estimate homography: need ≥4 points, got {len(src_pts)}. "
                f"Provide more feature matches."
            )
            return None, None

        def valid(matrix):
            if frame_size is None:
                return GeometryTransforms.is_matrix_valid(matrix, is_homography=True)
            from src.geometry.frame_transform import affine_at_center, valid_footprint

            if matrix is None or not valid_footprint(matrix, *frame_size, orientation=1):
                return False
            inverse = np.linalg.inv(matrix)
            if not valid_footprint(inverse, *frame_size, orientation=1):
                return False
            # Judge local scale, not the top-left block of a projective matrix.
            scale = np.linalg.svd(affine_at_center(matrix, *frame_size)[:, :2], compute_uv=False)
            return 0.1 < scale.min() and scale.max() < 10.0

        # PoseLib backend (LO-RANSAC)
        if backend == "poselib" and _POSELIB_AVAILABLE:
            H, mask = GeometryTransforms._estimate_homography_poselib(
                src_pts, dst_pts, ransac_threshold, max_iters, confidence
            )
            if valid(H):
                if use_mad_ransac:
                    mask = GeometryTransforms._refine_mask_mad(
                        src_pts, dst_pts, H, mask, mad_k_factor, ransac_threshold
                    )
                return H, mask
            # Fallback if PoseLib produced invalid matrix
            logger.debug("PoseLib homography invalid, falling back to OpenCV")

        # OpenCV backend (USAC_MAGSAC)
        src_pts_cv = src_pts.reshape(-1, 1, 2).astype(np.float64)
        dst_pts_cv = dst_pts.reshape(-1, 1, 2).astype(np.float64)

        H, mask = cv2.findHomography(
            src_pts_cv,
            dst_pts_cv,
            method=cv2.USAC_MAGSAC,
            ransacReprojThreshold=ransac_threshold,
            maxIters=max_iters,
            confidence=confidence,
        )

        # Validate Homography
        if not valid(H):
            if fallback_to_affine:
                logger.warning(
                    f"Homography invalid/degenerate (src_pts={len(src_pts)}, threshold={ransac_threshold}). "
                    f"Falling back to Full Affine (6 DoF)."
                )
                M, mask = GeometryTransforms.estimate_affine(src_pts, dst_pts, ransac_threshold)
                if M is not None:
                    H_fallback = np.vstack([M, [0, 0, 1]])
                    return H_fallback, mask
                return None, None
            logger.warning(
                f"Homography invalid/degenerate and no fallback enabled | "
                f"src_pts={len(src_pts)}, threshold={ransac_threshold}"
            )
            return None, None

        # MAD-RANSAC: adaptive inlier mask refinement (shrinks mask only)
        if use_mad_ransac and H is not None:
            mask = GeometryTransforms._refine_mask_mad(
                src_pts, dst_pts, H, mask, mad_k_factor, ransac_threshold
            )

        return H, mask

    @staticmethod
    def _estimate_homography_poselib(
        src_pts: np.ndarray,
        dst_pts: np.ndarray,
        ransac_threshold: float = 3.0,
        max_iters: int = 2000,
        confidence: float = 0.99,
    ):
        """
        Estimate Homography via PoseLib LO-RANSAC.
        Returns (H, mask) in OpenCV compatible format.
        """
        pts_src = src_pts.reshape(-1, 2).astype(np.float64)
        pts_dst = dst_pts.reshape(-1, 2).astype(np.float64)

        ransac_opt = {
            "max_reproj_error": ransac_threshold,
            "max_iterations": max_iters,
            "confidence": confidence,
        }

        H, info = poselib.estimate_homography(pts_src, pts_dst, ransac_opt)

        if H is None:
            return None, None

        # Convert inlier mask to (N, 1) uint8 format — OpenCV analog.
        # PoseLib returns info["inliers"] as one bool PER POINT, not a list of
        # indices. The old loop ``mask[idx] = 1`` indexed with those bools:
        # numpy treats a scalar True as "select everything", so any inlier set
        # the WHOLE mask to 1 — every match counted as an inlier. With
        # homography.use_mad_ransac=true the MAD refinement re-thresholded all
        # points under H and hid this; with it off, outliers went straight into
        # the inlier count, the RMSE gate and the spread estimate.
        n_pts = len(pts_src)
        flags = np.asarray(info.get("inliers", []), dtype=bool).ravel()
        if flags.size != n_pts:
            logger.warning(
                f"PoseLib inlier mask has {flags.size} entries for {n_pts} points — "
                "falling back to OpenCV"
            )
            return None, None
        mask = flags.astype(np.uint8).reshape(-1, 1)

        return np.array(H, dtype=np.float64), mask

    @staticmethod
    def apply_homography(points: np.ndarray, H: np.ndarray) -> np.ndarray:
        if H is None or len(points) == 0:
            return points
        points_cv = points.reshape(-1, 1, 2).astype(np.float64)
        transformed_pts_cv = cv2.perspectiveTransform(points_cv, H.astype(np.float64))
        return transformed_pts_cv.reshape(-1, 2)

    @staticmethod
    def estimate_affine_lsq(src_pts: np.ndarray, dst_pts: np.ndarray) -> np.ndarray | None:
        """Deterministic least-squares fit of full 6-DoF affine matrix.

        Uses all points and produces deterministic results. Intended for calibration
        anchors (4-8 user-verified points) where non-deterministic RANSAC is undesirable.
        """
        if src_pts is None or len(src_pts) < 3:
            logger.debug(
                f"Cannot LSQ-fit affine: need ≥3 points, got "
                f"{0 if src_pts is None else len(src_pts)}"
            )
            return None

        src = np.asarray(src_pts, dtype=np.float64).reshape(-1, 2)
        dst = np.asarray(dst_pts, dtype=np.float64).reshape(-1, 2)
        n = len(src)

        A = np.zeros((2 * n, 6), dtype=np.float64)
        b = np.zeros(2 * n, dtype=np.float64)
        A[0::2, 0] = src[:, 0]
        A[0::2, 1] = src[:, 1]
        A[0::2, 2] = 1.0
        A[1::2, 3] = src[:, 0]
        A[1::2, 4] = src[:, 1]
        A[1::2, 5] = 1.0
        b[0::2] = dst[:, 0]
        b[1::2] = dst[:, 1]

        sol, _, rank, _ = np.linalg.lstsq(A, b, rcond=None)
        if rank < 6:
            logger.debug("LSQ affine fit degenerate (points nearly collinear?)")
            return None
        return sol.reshape(2, 3)

    @staticmethod
    def estimate_affine(src_pts: np.ndarray, dst_pts: np.ndarray, ransac_threshold: float = 3.0):
        """Compute full Affine transformation (6 DoF) using MAGSAC++"""
        if len(src_pts) < 3:
            logger.debug(f"Cannot estimate affine: need ≥3 points, got {len(src_pts)}")
            return None, None

        src_pts_cv = src_pts.reshape(-1, 1, 2).astype(np.float64)
        dst_pts_cv = dst_pts.reshape(-1, 1, 2).astype(np.float64)

        M, mask = cv2.estimateAffine2D(
            src_pts_cv, dst_pts_cv, method=cv2.RANSAC, ransacReprojThreshold=ransac_threshold
        )

        if not GeometryTransforms.is_matrix_valid(M, is_homography=False):
            logger.debug(
                f"Affine estimation produced invalid matrix | "
                f"src_pts={len(src_pts)}, threshold={ransac_threshold}"
            )
            return None, None

        return M, mask

    @staticmethod
    def estimate_affine_partial(
        src_pts: np.ndarray, dst_pts: np.ndarray, ransac_threshold: float = 3.0
    ):
        """Compute STRICT Affine transformation (4 DoF: R+T+S only) using MAGSAC++"""
        if len(src_pts) < 2:
            logger.debug(f"Cannot estimate partial affine: need ≥2 points, got {len(src_pts)}")
            return None, None

        src_pts_cv = src_pts.reshape(-1, 1, 2).astype(np.float64)
        dst_pts_cv = dst_pts.reshape(-1, 1, 2).astype(np.float64)

        M, mask = cv2.estimateAffinePartial2D(
            src_pts_cv, dst_pts_cv, method=cv2.RANSAC, ransacReprojThreshold=ransac_threshold
        )

        if not GeometryTransforms.is_matrix_valid(M, is_homography=False):
            logger.debug(
                f"Partial affine estimation produced invalid matrix | "
                f"src_pts={len(src_pts)}, threshold={ransac_threshold}"
            )
            return None, None

        return M, mask

    @staticmethod
    def apply_affine(points: np.ndarray, M: np.ndarray) -> np.ndarray:
        if M is None or len(points) == 0:
            return points
        if M.shape == (3, 3):
            # Full projective maps must retain the homogeneous denominator.
            # Keep this compatibility entry point for callers with old affines.
            from src.geometry.frame_transform import project_points

            return project_points(M, points)
        points_cv = points.reshape(-1, 1, 2).astype(np.float64)
        transformed_pts_cv = cv2.transform(points_cv, M.astype(np.float64))
        return transformed_pts_cv.reshape(-1, 2)


