# File: src\localization\geometric_verifier.py
# ================================================================================
"""Geometric verification: candidate matching + RANSAC homography (IMPROVEMENT_PLAN 1.1).

Extracted verbatim from Localizer.localize_frame's candidate loop. Stateless: the
frame database is passed to ``verify`` explicitly because it is switched per-source
in multi-database mode.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Any

import cv2
import numpy as np

from src.geometry.transformations import GeometryTransforms
from src.utils.logging_utils import get_logger
from src.utils.telemetry import Telemetry

logger = get_logger(__name__)


@dataclass
class VerificationResult:
    candidate_id: int
    H_query_to_ref: np.ndarray
    inliers: int
    mkpts_q_in: np.ndarray
    mkpts_r_in: np.ndarray
    total_matches: int
    rmse: float


class GeometricVerifier:
    """Match each candidate, estimate a homography, keep the best (with early stop)."""

    def __init__(
        self,
        matcher: Any,
        min_matches: int,
        ransac_thresh: float,
        homography_backend: str,
        use_mad_ransac: bool,
        mad_k_factor: float,
        early_stop_inliers: int,
        prefilter_enabled: bool = False,
        prefilter_keep: int = 2,
        max_rmse_px: float = 4.0,
        min_inlier_ratio: float = 0.2,
        max_center_extrapolation: float = 0.1,
        min_reference_eigenvalue: float = 1e-4,
        ransac_max_iters: int = 2000,
        ransac_confidence: float = 0.99,
        prefilter_fallback_keep: int = 0,
    ) -> None:
        self.matcher = matcher
        self.min_matches = min_matches
        self.ransac_thresh = ransac_thresh
        self.homography_backend = homography_backend
        self.use_mad_ransac = use_mad_ransac
        self.mad_k_factor = mad_k_factor
        self.early_stop_inliers = early_stop_inliers
        self.prefilter_enabled = prefilter_enabled
        self.prefilter_keep = prefilter_keep
        self.max_rmse_px = float(max_rmse_px)
        self.min_inlier_ratio = float(min_inlier_ratio)
        self.max_center_extrapolation = float(max_center_extrapolation)
        self.min_reference_eigenvalue = float(min_reference_eigenvalue)
        self.ransac_max_iters = int(ransac_max_iters)
        self.ransac_confidence = float(ransac_confidence)
        # When no candidate has a single MNN pair, LightGlue only the first N by
        # global score instead of the whole list. 0 = whole list (old behaviour).
        self.prefilter_fallback_keep = int(prefilter_fallback_keep)
        # Diagnostics only (replay sets a list per frame): one record per verify()
        # call with every candidate's prefilter pairs and LightGlue / RANSAC
        # outcome. None = off; nothing below changes what verify() returns.
        self.trace: list | None = None
        # MNN pairs of the last mnn_counts() call while tracing:
        # {candidate_id: [pairs at Lowe ratio 0.75 (used), 0.85, 0.95]}.
        self._last_mnn: dict | None = None

    def _has_spatial_support(
        self,
        query_features: dict,
        pts_q_in: np.ndarray,
        pts_r_in: np.ndarray,
        H_query_to_ref: np.ndarray,
    ) -> bool:
        """Require inliers to support projecting the query image centre.

        A low reprojection error only proves that a local patch is consistent.
        It does not make extrapolation across the rest of the frame safe.  This
        check rejects near-collinear reference geometry, centres far outside the
        query inlier hull, and homographies with a pole inside the query frame.
        """
        size = np.asarray(query_features.get("image_size", []), dtype=float).ravel()
        if size.size < 2 or not np.isfinite(size[:2]).all():
            logger.debug("Rejecting geometry: query image_size is missing or invalid")
            return False
        height, width = map(float, size[:2])
        if height <= 0 or width <= 0:
            return False

        q_points = np.asarray(pts_q_in, dtype=np.float32).reshape(-1, 2)
        r_points = np.asarray(pts_r_in, dtype=np.float64).reshape(-1, 2)
        if len(q_points) < 3 or len(r_points) < 3:
            return False

        hull = cv2.convexHull(q_points)
        center = (width / 2.0, height / 2.0)
        distance = cv2.pointPolygonTest(hull, center, True)
        max_outside = self.max_center_extrapolation * float(np.hypot(width, height))
        if distance < -max_outside:
            logger.debug(
                f"Rejecting geometry: query centre is {-distance:.1f}px outside "
                f"inlier support (limit {max_outside:.1f}px)"
            )
            return False

        extents = np.ptp(r_points, axis=0)
        if np.min(extents) <= 1e-6:
            logger.debug("Rejecting geometry: reference inliers are spatially degenerate")
            return False
        normalized = (r_points - r_points.mean(axis=0)) / extents
        eigenvalues = np.linalg.eigvalsh(normalized.T @ normalized / len(normalized))
        if eigenvalues[0] < self.min_reference_eigenvalue:
            logger.debug(
                f"Rejecting geometry: reference inliers are near-collinear "
                f"(eigenvalue {eigenvalues[0]:.2e})"
            )
            return False

        H = np.asarray(H_query_to_ref, dtype=np.float64)
        if H.shape != (3, 3) or not np.isfinite(H).all():
            return False
        corners = np.array(
            [[0.0, 0.0, 1.0], [width, 0.0, 1.0], [width, height, 1.0], [0.0, height, 1.0]]
        )
        denominators = corners @ H[2]
        if not (
            np.all(denominators > 1e-9) or np.all(denominators < -1e-9)
        ):
            logger.debug("Rejecting geometry: homography has a pole inside the query frame")
            return False
        return True

    def verify(
        self,
        query_features: dict,
        candidates: list,
        database: Any,
        ref_cache: dict | None = None,
        tag: str | None = None,
    ) -> VerificationResult | None:
        """``tag`` names the caller in ``trace`` records (temporal_prior, retrieval, refine)."""
        rec = None
        if self.trace is not None:
            rec = {
                "tag": tag,
                "input": [[int(c), round(float(sc), 4)] for c, sc in candidates],
                "prefilter": None,
                "tried": [],
                "winner": None,
                "early_stop": False,
            }
            self.trace.append(rec)
            self._last_mnn = None
        best_inliers = 0
        best_candidate_id = -1
        best_H_query_to_ref = None
        best_mkpts_q_inliers = None
        best_mkpts_r_inliers = None
        best_total_matches = 0
        best_rmse = 999.0

        early_stop = self.early_stop_inliers

        # ADDENDUM item 1: cheap MNN-scoring of all candidates, LightGlue — only
        # on top ones. ref_cache avoids redundant DB feature reading.
        ref_cache = {} if ref_cache is None else ref_cache
        if self.prefilter_enabled and len(candidates) > self.prefilter_keep:
            candidates = self._prefilter(query_features, candidates, database, ref_cache)
            if rec is not None:
                mnn = self._last_mnn or {}
                rec["prefilter"] = {
                    "pairs": {str(c): v for c, v in mnn.items()},
                    "all_zero": bool(mnn) and all(v[0] == 0 for v in mnn.values()),
                    "kept": [int(c) for c, _ in candidates],
                }

        for candidate_id, score in candidates:
            logger.debug(f"  → Trying candidate {candidate_id} (global_score={score:.3f})")
            ref_features = ref_cache.get(candidate_id)
            if ref_features is None:
                with Telemetry.profile("ref_read"):
                    ref_features = database.get_local_features(candidate_id)

            with Telemetry.profile("match"):
                mkpts_q, mkpts_r = self.matcher.match(query_features, ref_features)
            tried = None
            if rec is not None:
                tried = {
                    "cid": int(candidate_id),
                    "matches": int(len(mkpts_q)),
                    "result": "few_matches",
                }
                rec["tried"].append(tried)

            if len(mkpts_q) >= self.min_matches:
                with Telemetry.profile("ransac_homography"):
                    H_eval, mask = GeometryTransforms.estimate_homography(
                        mkpts_q,
                        mkpts_r,
                        ransac_threshold=self.ransac_thresh,
                        max_iters=self.ransac_max_iters,
                        confidence=self.ransac_confidence,
                        backend=self.homography_backend,
                        use_mad_ransac=self.use_mad_ransac,
                        mad_k_factor=self.mad_k_factor,
                    )

                if tried is not None:
                    tried["result"] = "no_homography"
                if H_eval is not None:
                    inlier_mask = mask.ravel().astype(bool)
                    inliers = int(np.sum(inlier_mask))
                    pts_q_in = mkpts_q[inlier_mask]
                    pts_r_in = mkpts_r[inlier_mask]

                    pts_q_transformed = GeometryTransforms.apply_homography(pts_q_in, H_eval)
                    rmse = float(
                        np.sqrt(np.mean(np.sum((pts_q_transformed - pts_r_in) ** 2, axis=1)))
                    )

                    inlier_ratio = inliers / max(1, len(mkpts_q))
                    if tried is not None:
                        tried["inliers"] = inliers
                        tried["rmse"] = round(rmse, 3) if np.isfinite(rmse) else None
                        tried["result"] = "rmse"
                    if not np.isfinite(rmse) or rmse > self.max_rmse_px:
                        logger.debug(
                            f"Rejecting candidate {candidate_id}: RMSE {rmse:.2f}px > "
                            f"{self.max_rmse_px:.2f}px"
                        )
                        continue
                    if tried is not None:
                        tried["result"] = "inlier_ratio"
                    if inlier_ratio < self.min_inlier_ratio:
                        logger.debug(
                            f"Rejecting candidate {candidate_id}: inlier ratio "
                            f"{inlier_ratio:.3f} < {self.min_inlier_ratio:.3f}"
                        )
                        continue
                    if tried is not None:
                        tried["result"] = "spatial_support"
                    if not self._has_spatial_support(
                        query_features, pts_q_in, pts_r_in, H_eval
                    ):
                        continue
                    if tried is not None:
                        tried["result"] = "ok" if inliers >= self.min_matches else "few_inliers"

                    if inliers > best_inliers and inliers >= self.min_matches:
                        best_inliers = inliers
                        best_candidate_id = candidate_id
                        best_H_query_to_ref = H_eval
                        best_mkpts_q_inliers = pts_q_in
                        best_mkpts_r_inliers = pts_r_in
                        best_total_matches = len(mkpts_q)
                        best_rmse = rmse
                        logger.debug(
                            f"Homography for {candidate_id}: {inliers} inliers, RMSE: {rmse:.2f}"
                        )

            if best_inliers >= early_stop:
                logger.debug(
                    f"Early stop triggered with {best_inliers} inliers on candidate {best_candidate_id}"
                )
                if rec is not None:
                    rec["early_stop"] = True
                break

        if rec is not None and best_candidate_id != -1 and best_inliers >= self.min_matches:
            rec["winner"] = [int(best_candidate_id), int(best_inliers)]

        if (
            best_inliers < self.min_matches
            or best_mkpts_r_inliers is None
            or best_H_query_to_ref is None
        ):
            return None

        return VerificationResult(
            candidate_id=best_candidate_id,
            H_query_to_ref=best_H_query_to_ref,
            inliers=best_inliers,
            mkpts_q_in=best_mkpts_q_inliers,
            mkpts_r_in=best_mkpts_r_inliers,
            total_matches=best_total_matches,
            rmse=best_rmse,
        )

    # -- ADDENDUM item 1: candidate MNN-prefilter --------------------------

    def mnn_counts(
        self,
        query_features: dict,
        candidates: list,
        database: Any,
        ref_cache: dict | None = None,
    ) -> list[tuple[int, int, float]] | None:
        """Number of mutual-NN pairs (with Lowe ratio) between query and each candidate.

        Повертає ``[(пар, candidate_id, score), ...]`` або ``None``, якщо
        дескриптори query вироджені. Два споживачі:
        передфільтр нижче (ADDENDUM §1) і темпоральний prior
        (PIPELINE_OPTIMIZATION_PLAN §A1), для якого це дешева проба гіпотези —
        один матмул замість повного LightGlue.

        Lowe ratio обовʼязковий: голий mutual-NN рахує ~50% випадкових пар
        між будь-якими наборами (перевірено юніт-тестом), ratio їх зрізає.
        Той самий поріг, що і в ``_fast_numpy_match`` (L2-нормовані
        дескриптори: d = sqrt(2-2s)). GPU-шлях (один матмул на кандидата)
        з фолбеком на numpy.
        """
        q = np.asarray(query_features.get("descriptors")) if query_features else None
        if q is None or q.ndim != 2 or len(q) == 0:
            return None
        q32 = np.ascontiguousarray(q, dtype=np.float32)

        use_torch = False
        q_t = None
        try:
            import torch

            if torch.cuda.is_available():
                q_t = torch.from_numpy(q32).cuda()
                use_torch = True
        except Exception:  # noqa: BLE001 — GPU-шлях опційний, фолбек numpy
            use_torch = False

        ratio = 0.75
        gpu_failed = False

        tracing = self.trace is not None
        traced: dict = {}
        # Pairs at looser Lowe ratios, recorded only while tracing (diagnostics).
        extra_ratios = (0.85, 0.95)
        last_extra = [0, 0]

        def _mnn_count(r: np.ndarray) -> int:
            nonlocal use_torch, gpu_failed, last_extra
            r32 = np.ascontiguousarray(r, dtype=np.float32)
            last_extra = [0, 0]
            if r32.shape[0] < 2:
                return 0
            if use_torch:
                try:
                    r_t = torch.from_numpy(r32).cuda()
                    sim = q_t @ r_t.T
                    top2 = torch.topk(sim, 2, dim=1).values
                    d1 = torch.sqrt(torch.clamp(2.0 - 2.0 * top2[:, 0], min=0.0))
                    d2 = torch.sqrt(torch.clamp(2.0 - 2.0 * top2[:, 1], min=0.0))
                    ratio_ok = d1 < ratio * d2
                    nn12 = sim.argmax(dim=1)
                    nn21 = sim.argmax(dim=0)
                    idx = torch.arange(sim.shape[0], device=sim.device)
                    if tracing:
                        mutual_t = nn21[nn12] == idx
                        last_extra = [
                            int((mutual_t & (d1 < t * d2)).sum().item()) for t in extra_ratios
                        ]
                    return int(((nn21[nn12] == idx) & ratio_ok).sum().item())
                except Exception as e:  # noqa: BLE001 — OOM тощо → numpy
                    # Silent fallback to numpy is a performance drop that
                    # was completely hidden before. Disable GPU path for remaining
                    # call and report once.
                    if not gpu_failed:
                        gpu_failed = True
                        logger.warning(
                            f"GPU MNN path failed — falling back to numpy for this "
                            f"verification ({type(e).__name__}: {e})"
                        )
                    use_torch = False
            sim = q32 @ r32.T
            top2 = -np.partition(-sim, 1, axis=1)[:, :2]
            d1 = np.sqrt(np.clip(2.0 - 2.0 * top2[:, 0], 0.0, None))
            d2 = np.sqrt(np.clip(2.0 - 2.0 * top2[:, 1], 0.0, None))
            ratio_ok = d1 < ratio * d2
            nn12 = sim.argmax(axis=1)
            nn21 = sim.argmax(axis=0)
            mutual = nn21[nn12] == np.arange(sim.shape[0])
            if tracing:
                last_extra = [int(np.sum(mutual & (d1 < t * d2))) for t in extra_ratios]
            return int(np.sum(mutual & ratio_ok))

        scored: list[tuple[int, int, float]] = []
        with Telemetry.profile("prefilter"):
            for candidate_id, score in candidates:
                ref = ref_cache.get(candidate_id) if ref_cache is not None else None
                if ref is None:
                    try:
                        ref = database.get_local_features(candidate_id)
                    except (ValueError, KeyError) as e:
                        # Temporal prior suggests neighbors by index —
                        # some of them may be missing in DB. This is not an error.
                        logger.debug(f"MNN probe: candidate {candidate_id} unreadable ({e})")
                        scored.append((0, candidate_id, score))
                        continue
                    if ref_cache is not None:
                        ref_cache[candidate_id] = ref
                r = np.asarray(ref.get("descriptors"))
                if r is None or r.ndim != 2 or len(r) == 0 or r.shape[1] != q.shape[1]:
                    scored.append((0, candidate_id, score))
                    continue
                pairs = _mnn_count(r)
                scored.append((pairs, candidate_id, score))
                if tracing:
                    traced[int(candidate_id)] = [pairs, *last_extra]
        if tracing:
            self._last_mnn = traced
        return scored

    def _prefilter(
        self, query_features: dict, candidates: list, database: Any, ref_cache: dict
    ) -> list:
        """Ranks candidates by MNN match count and keeps top ``prefilter_keep``
        найкращих (LightGlue далі йде лише по них).

        Консервативність: якщо жоден кандидат не набрав жодної MNN-пари
        (виродження: порожні/несумісні дескриптори) — список без змін.
        """
        scored = self.mnn_counts(query_features, candidates, database, ref_cache)
        if scored is None:
            return candidates
        if all(s[0] == 0 for s in scored):
            if self.prefilter_fallback_keep > 0:
                # Measured 2026-10-10 on 6 routes: this case ran 63 % of all
                # LightGlue calls; 3 of its 163 calls found a frame, at global
                # positions 0, 3 and 0. MNN pairs at looser Lowe ratios did not
                # single them out, the retrieval order did.
                logger.debug(
                    f"Prefilter: no MNN pairs on any candidate — keeping the first "
                    f"{self.prefilter_fallback_keep} by global score"
                )
                return candidates[: self.prefilter_fallback_keep]
            logger.debug("Prefilter: no MNN pairs on any candidate — keeping full list")
            return candidates
        scored.sort(key=lambda t: (-t[0], -t[2]))
        kept = [(cid, sc) for _, cid, sc in scored[: self.prefilter_keep]]
        logger.debug(
            f"Prefilter kept {len(kept)}/{len(candidates)} candidates "
            f"(mnn top: {[(c, m) for m, c, _ in scored[: self.prefilter_keep]]})"
        )
        return kept


