# File: src\models\wrappers\vlad_aggregator.py
# ================================================================================
"""Untrained VLAD aggregation of patch tokens (AnyLoc, arXiv:2308.00688).

Replaces the global descriptor CLS token with VLAD over foundation model patch tokens:
vocabulary built via k-means over reference frame tokens, descriptor is concatenated normalized cluster residuals + PCA-whitening.
"""

from __future__ import annotations

import json

import numpy as np

from src.utils.logging_utils import get_logger

logger = get_logger(__name__)


class VladAggregator:
    """VLAD with hard assignment + intra-normalization + PCA-whitening."""

    def __init__(
        self,
        n_clusters: int = 32,
        pca_dim: int = 512,
        low_norm_fraction: float = 0.0,
        seed: int = 42,
    ) -> None:
        self.n_clusters = int(n_clusters)
        self.pca_dim = int(pca_dim)
        self.low_norm_fraction = float(low_norm_fraction)
        self.seed = int(seed)

        self.centers: np.ndarray | None = None  # (K, D)
        self.pca_mean: np.ndarray | None = None  # (K*D,)
        self.pca_components: np.ndarray | None = None  # (pca_dim, K*D)
        self.pca_eigvals: np.ndarray | None = None  # (pca_dim,)
        # How the vocabulary was built (sources, ViT layer, input size, ...); empty
        # for vocabularies saved before provenance was recorded.
        self.provenance: dict = {}

    @property
    def is_fitted(self) -> bool:
        return self.centers is not None

    @property
    def out_dim(self) -> int:
        """Dimensionality of the final descriptor."""
        if self.centers is None:
            raise RuntimeError("VladAggregator is not fitted")
        if self.pca_components is not None:
            return int(self.pca_components.shape[0])
        return int(self.n_clusters * self.centers.shape[1])

    def fit(
        self,
        tokens_per_image: list[np.ndarray],
        max_kmeans_tokens: int = 200_000,
    ) -> VladAggregator:
        """Builds vocabulary (k-means) and PCA-whitening over reference frames.

        Args:
            tokens_per_image: list of (N_i, D) patch tokens per frame.
            max_kmeans_tokens: cap on sampled tokens for k-means.
        """
        if len(tokens_per_image) < 2:
            raise ValueError("fit() needs at least 2 images of tokens")

        rng = np.random.default_rng(self.seed)
        total = sum(len(t) for t in tokens_per_image)
        if total > max_kmeans_tokens:
            # Sample per image instead of stacking everything first: at 448 px input
            # 3000 frames hold ~2.4M tokens (~10 GB float32), more than k-means needs.
            per_image = max(1, max_kmeans_tokens // len(tokens_per_image))
            parts = []
            for t in tokens_per_image:
                t = np.asarray(t)
                pick = rng.choice(len(t), size=min(per_image, len(t)), replace=False)
                parts.append(np.asarray(t[pick], dtype=np.float32))
            stacked = np.concatenate(parts, axis=0)
        else:
            stacked = np.concatenate(
                [np.asarray(t, dtype=np.float32) for t in tokens_per_image], axis=0
            )

        self.centers = self._kmeans(stacked)
        logger.info(
            f"VLAD vocabulary: k-means done | k={self.n_clusters}, "
            f"tokens={len(stacked)}, dim={stacked.shape[1]}"
        )

        # PCA-whitening over VLAD vectors of reference frames
        vlads = np.stack([self._vlad(t) for t in tokens_per_image])  # (M, K*D)
        n_samples, full_dim = vlads.shape
        eff_dim = min(self.pca_dim, n_samples - 1, full_dim)
        if eff_dim < self.pca_dim:
            logger.warning(
                f"PCA dim reduced {self.pca_dim} → {eff_dim}: "
                f"only {n_samples} reference images (need ≥ pca_dim+1 for full rank)"
            )
        if eff_dim < 2:
            logger.warning("PCA disabled: not enough reference images")
            self.pca_mean = None
            self.pca_components = None
            self.pca_eigvals = None
            return self

        self.pca_mean = vlads.mean(axis=0)
        centered = vlads - self.pca_mean
        _, s, vt = np.linalg.svd(centered, full_matrices=False)
        self.pca_components = vt[:eff_dim].astype(np.float32)
        self.pca_eigvals = (s[:eff_dim] ** 2 / max(n_samples - 1, 1)).astype(np.float32)
        logger.info(f"VLAD PCA-whitening fitted: {full_dim} → {eff_dim}")
        return self

    def _kmeans(self, tokens: np.ndarray) -> np.ndarray:
        """k-means: faiss (fast, GPU-capable) with fallback to scipy."""
        try:
            import faiss

            km = faiss.Kmeans(
                d=int(tokens.shape[1]),
                k=self.n_clusters,
                niter=25,
                seed=self.seed,
                verbose=False,
            )
            km.train(np.ascontiguousarray(tokens, dtype=np.float32))
            return km.centroids.reshape(self.n_clusters, -1).astype(np.float32)
        except ImportError:
            logger.info("faiss not available — falling back to scipy kmeans2")
            from scipy.cluster.vq import kmeans2

            centers, _ = kmeans2(
                tokens.astype(np.float64),
                self.n_clusters,
                minit="++",
                seed=self.seed,
            )
            return centers.astype(np.float32)

    def _filter_low_norm(self, tokens: np.ndarray) -> np.ndarray:
        """Discards low-norm tokens (uninformative background/sky regions)."""
        if self.low_norm_fraction <= 0.0 or len(tokens) < 8:
            return tokens
        norms = np.linalg.norm(tokens, axis=1)
        thresh = np.quantile(norms, self.low_norm_fraction)
        kept = tokens[norms > thresh]
        return kept if len(kept) >= 4 else tokens

    def _vlad(self, tokens: np.ndarray) -> np.ndarray:
        """VLAD vector without PCA: (K*D,) with intra- and global L2-normalization."""
        if self.centers is None:
            raise RuntimeError("VladAggregator is not fitted")
        t = self._filter_low_norm(np.asarray(tokens, dtype=np.float32))
        k, d = self.centers.shape

        # Hard assignment to nearest centroid
        dots = t @ self.centers.T  # (N, K)
        c_sq = np.sum(self.centers**2, axis=1)  # (K,)
        assign = np.argmax(dots - 0.5 * c_sq, axis=1)  # (N,)

        vlad = np.zeros((k, d), dtype=np.float32)
        for ci in range(k):
            sel = t[assign == ci]
            if len(sel):
                vlad[ci] = (sel - self.centers[ci]).sum(axis=0)

        # Intra-normalization
        norms = np.linalg.norm(vlad, axis=1, keepdims=True)
        np.divide(vlad, norms, out=vlad, where=norms > 1e-12)

        flat = vlad.reshape(-1)
        n = np.linalg.norm(flat)
        return flat / n if n > 1e-12 else flat

    # A partially valid view (rotated query: black wedges outside the frame)
    # aggregates only its valid tokens; below this count all tokens are kept.
    MIN_VALID_TOKENS = 16

    def aggregate(self, tokens: np.ndarray, valid: np.ndarray | None = None) -> np.ndarray:
        """Patch tokens (N, D) -> global descriptor (out_dim,), L2-normalized.

        ``valid`` (N,) bool selects the tokens to aggregate (None = all).
        VLAD is a sum over tokens, so a subset is a well-defined descriptor of
        the visible content; the database side always passes None.
        """
        if valid is not None:
            valid = np.asarray(valid, dtype=bool).ravel()
            if valid.shape[0] == len(tokens) and int(valid.sum()) >= self.MIN_VALID_TOKENS:
                tokens = np.asarray(tokens)[valid]
        v = self._vlad(tokens)
        if self.pca_components is not None:
            v = (v - self.pca_mean) @ self.pca_components.T
            v = v / np.sqrt(self.pca_eigvals + 1e-8)
            n = np.linalg.norm(v)
            if n > 1e-12:
                v = v / n
        return v.astype(np.float32)

    def aggregate_batch(
        self,
        tokens_batch: np.ndarray | list[np.ndarray],
        valid_batch: list[np.ndarray | None] | None = None,
    ) -> np.ndarray:
        """(B, N, D) or list of (N_i, D) -> (B, out_dim)."""
        if valid_batch is None:
            return np.stack([self.aggregate(t) for t in tokens_batch])
        return np.stack([self.aggregate(t, v) for t, v in zip(tokens_batch, valid_batch)])

    def save(self, path: str, provenance: dict | None = None) -> None:
        if self.centers is None:
            raise RuntimeError("Nothing to save: not fitted")
        if provenance is not None:
            self.provenance = dict(provenance)
        np.savez_compressed(
            path,
            centers=self.centers,
            pca_mean=self.pca_mean if self.pca_mean is not None else np.empty(0),
            pca_components=(
                self.pca_components if self.pca_components is not None else np.empty((0, 0))
            ),
            pca_eigvals=self.pca_eigvals if self.pca_eigvals is not None else np.empty(0),
            meta=np.array([self.n_clusters, self.pca_dim, self.seed], dtype=np.int64),
            low_norm_fraction=np.float64(self.low_norm_fraction),
            provenance_json=np.array(json.dumps(self.provenance, sort_keys=True)),
        )
        logger.info(f"VLAD vocabulary saved: {path} (out_dim={self.out_dim})")

    @classmethod
    def load(cls, path: str, low_norm_fraction: float | None = None) -> VladAggregator:
        data = np.load(path, allow_pickle=False)
        n_clusters, pca_dim, seed = (int(x) for x in data["meta"])
        lnf = (
            float(data["low_norm_fraction"])
            if low_norm_fraction is None
            else float(low_norm_fraction)
        )
        agg = cls(n_clusters=n_clusters, pca_dim=pca_dim, low_norm_fraction=lnf, seed=seed)
        agg.centers = data["centers"].astype(np.float32)
        if data["pca_components"].size:
            agg.pca_mean = data["pca_mean"].astype(np.float32)
            agg.pca_components = data["pca_components"].astype(np.float32)
            agg.pca_eigvals = data["pca_eigvals"].astype(np.float32)
        if "provenance_json" in data.files:
            agg.provenance = json.loads(str(data["provenance_json"]))
        logger.info(f"VLAD vocabulary loaded: {path} | k={n_clusters}, out_dim={agg.out_dim}")
        return agg


def provenance_mismatches(provenance: dict, expected: dict) -> list[str]:
    """Settings recorded in a vocabulary's provenance that differ from ``expected``.

    Keys missing from the provenance (older vocabularies) are not reported.
    """
    return [
        f"{key}: vocabulary {provenance[key]!r} != config {value!r}"
        for key, value in expected.items()
        if key in provenance and provenance[key] != value
    ]


