from dataclasses import dataclass

import numpy as np

try:
    import supervision as sv
except ImportError:
    sv = None


@dataclass
class TrackedObject:
    track_id: int
    class_id: int
    class_name: str
    bbox: tuple[float, float, float, float]  # (x1, y1, x2, y2)
    confidence: float
    center_px: tuple[float, float]  # (x, y)


class ObjectTracker:
    """Thin wrapper over ByteTrack for multi-object tracking between frames."""

    def __init__(self, config: dict):
        self.config = config
        # object_tracking.tracked_classes: empty / None = every detected class.
        classes = self.config.get("tracked_classes")
        self._tracked_classes = {int(c) for c in classes} if classes else None

        if sv is None:
            raise ImportError(
                "Package 'supervision' is required for ObjectTracker. Run 'pip install supervision'"
            )

        self.tracker = sv.ByteTrack(
            track_activation_threshold=self.config.get("track_activation_threshold", 0.25),
            lost_track_buffer=self.config.get("lost_track_buffer", 30),
            minimum_matching_threshold=self.config.get("minimum_matching_threshold", 0.8),
            frame_rate=30,  # Default
        )

