from collections import deque

import numpy as np

from src.utils.logging_utils import get_logger

logger = get_logger(__name__)


class OutlierDetector:
    """Detect anomalous measurements (outliers) based on trajectory history using speeds"""

    def __init__(
        self,
        window_size=10,
        threshold_std=3.0,
        max_speed_mps=1000.0,
        max_consecutive=5,
        ground_scale=1.0,
        zscore_enabled=True,
        mahalanobis_enabled=False,
        chi2_threshold=13.816,
        reacquire_consistent=False,
        reacquire_tol_m=15.0,
        reacquire_max_wait=10,
    ):
        self.window = deque(maxlen=window_size)
        self.threshold_std = threshold_std
        self.max_speed_mps = max_speed_mps
        self._consecutive_outliers = 0
        self._max_consecutive = max_consecutive
        # Projection-to-ground-metres multiplier (ground_scale). 1.0 = legacy
        # Without this correction WebMercator distances at 48° latitude are
        # inflated by 1/cos(lat) ≈ 1.49×, so max_speed_mps=120 effectively gates
        # at 80.6 m/s and ~39% of rejections on a live run were clean false positives.
        self._ground_scale = float(ground_scale)
        # Z-score branch. Measured on mission top 2026-07-31 (of_stride=1,
        # of_local_speed=ON): of 70 rejections 47 came from this branch, and ALL
        # 23 rejections on CORRECT measurements (distance 2.3-4.5 m at the 3.0 m
        # nominal) — also from this branch. Not a single real jump (>12 m) was
        # caught here: those are all caught by the physical max_speed guard.
        # Root cause: a self-sustaining loop — the gate rejects everything above
        # mean_speed, so only slow measurements enter the window, mean drops
        # (11.9-78 m/s vs. the true 89.2 m/s) and even more gets rejected.
        # Also std hits the 1.0 floor and z reaches 159.
        self._zscore_enabled = bool(zscore_enabled)
        # Mahalanobis gate (flag, default off): uses the χ² distance from the KF
        # innovation covariance instead of the Z-score on speed. Default threshold
        # is χ²(2 dof, p=0.999) = 13.816, i.e. ~0.1% false rejections on a
        # correct model. Branch is independent from Z-score: both can be enabled,
        # but the point of switching is to disable Z-score.
        self._mahalanobis_enabled = bool(mahalanobis_enabled)
        self._chi2_threshold = float(chi2_threshold)
        # Re-acquisition gate (flag, default off = legacy). Legacy behaviour
        # accepts the N-th consecutive rejected measurement unconditionally —
        # a direct jump mechanism when the rejections are random false fixes.
        # With the flag on, the streak is accepted only once two consecutive
        # rejected candidates sit at a CONSISTENT offset from the KF prediction
        # (a real relocation: the filter is wrong by a stable vector). Random
        # false fixes scatter and keep being rejected. ``reacquire_max_wait``
        # extra rejections cap the wait (0 = never force), so a filter that is
        # truly lost cannot lock out every measurement forever.
        self._reacquire = bool(reacquire_consistent)
        self._reacquire_tol_m = max(float(reacquire_tol_m), 0.0)
        self._reacquire_max_wait = max(int(reacquire_max_wait), 0)
        self._streak_offsets: list[np.ndarray] = []
        self._streak_no_pred = False

        logger.info("Initializing OutlierDetector (Speed-based Z-score)")
        logger.info(
            f"Parameters: window_size={window_size}, threshold_std={threshold_std}, max_speed_mps={max_speed_mps}"
        )

    def set_ground_scale(self, scale: float) -> None:
        """Updates the multiplier projection→ground meters (cos(lat) for WebMercator).

        Called from the localizer when a fresh latitude is available. Values <= 0
        are ignored — it is better to keep the previous one than zero out all speeds.
        """
        s = float(scale)
        if s > 0.0:
            self._ground_scale = s

    def reset(self) -> None:
        """Full state reset (new tracking session)."""
        self.window.clear()
        self._consecutive_outliers = 0
        self._streak_offsets.clear()

    def _note_rejection(self, new_pos_np: np.ndarray, pred_position) -> None:
        """Count one rejected measurement and remember its offset from the KF
        prediction (ground metres) for the re-acquisition consistency test."""
        self._consecutive_outliers += 1
        self._streak_no_pred = pred_position is None
        if pred_position is None:
            self._streak_offsets.clear()
            return
        off = (new_pos_np - np.asarray(pred_position, dtype=np.float64)) * self._ground_scale
        self._streak_offsets.append(off)
        del self._streak_offsets[:-2]

    def _streak_accept(self) -> bool:
        """Should the current rejection streak be accepted now?"""
        if self._consecutive_outliers < self._max_consecutive:
            return False
        if not self._reacquire or self._streak_no_pred:
            # legacy: N-th rejection is accepted unconditionally (also when no
            # KF prediction exists to test consistency against)
            return True
        if len(self._streak_offsets) == 2:
            drift = float(np.linalg.norm(self._streak_offsets[1] - self._streak_offsets[0]))
            if drift <= self._reacquire_tol_m:
                logger.warning(
                    f"OUTLIER RE-ACQUIRE: two consecutive rejected fixes agree "
                    f"(offset change {drift:.1f} m <= {self._reacquire_tol_m:.1f} m)"
                )
                return True
        if (
            self._reacquire_max_wait > 0
            and self._consecutive_outliers >= self._max_consecutive + self._reacquire_max_wait
        ):
            logger.warning(
                f"OUTLIER RE-ACQUIRE: forced after {self._consecutive_outliers} "
                f"inconsistent rejections"
            )
            return True
        return False

    def _accept_streak(self) -> None:
        self.window.clear()
        self._consecutive_outliers = 0
        self._streak_offsets.clear()

    def add_position(self, position: tuple, dt: float = 1.0, reset_consecutive: bool = True):
        # Now we store both position and dt (time it took to reach this position)
        self.window.append((np.array(position, dtype=np.float64), max(dt, 0.01)))
        if reset_consecutive:
            self._consecutive_outliers = 0
            self._streak_offsets.clear()

    def is_outlier(
        self,
        new_position: tuple,
        dt: float = 1.0,
        ref_position: tuple | None = None,
        maha_d2: float | None = None,
        pred_position: tuple | None = None,
    ) -> bool:
        """Anomaly detection for measurements.

        ``ref_position`` — reference point for INSTANTANEOUS speed. By default
        it takes the last ACCEPTED position from the window, but on the OF-path
        this is incorrect: LK always tracks from a keyframe (tracking_worker.py:486),
        so the shift grows linearly from the keyframe, while dt remains a step of
        one OF-frame. Bases of the numerator and denominator differ -> speed is
        inflated exactly by N times, where N is the number of the OF-frame after
        the keyframe. Measured on mission top 2026-07-31: logged 450-1271 m/s fall
        onto a grid N * 89.2 m/s at N=5..14, and exactly 10 OF-frames fit between
        keyframe-s.

        Passing the previous RAW OF-position as ref_position makes the calculation
        local (frame relative to frame) and removes accumulation.

        ``pred_position`` — KF prediction for this measurement time; used only by
        the re-acquisition gate (``reacquire_consistent``). None = legacy.
        """
        # The Mahalanobis branch does not need a speed window: the filter
        # covariance already encodes the full history. It is therefore checked
        # BEFORE the early exit on window length — otherwise the first frames
        # after a reset would have no gate except the physical speed limit.
        is_maha_outlier = (
            self._mahalanobis_enabled and maha_d2 is not None and maha_d2 > self._chi2_threshold
        )

        if len(self.window) < 3:
            if is_maha_outlier:
                self._note_rejection(np.array(new_position, dtype=np.float64), pred_position)
                if self._streak_accept():
                    logger.warning(
                        f"OUTLIER RESET: {self._consecutive_outliers} consecutive outliers — "
                        f"accepting new position (mahalanobis d2={maha_d2:.1f})"
                    )
                    self._accept_streak()
                    return False
                logger.warning(
                    f"OUTLIER DETECTED (mahalanobis): d2={maha_d2:.2f} > "
                    f"{self._chi2_threshold:.2f} | consecutive="
                    f"{self._consecutive_outliers}/{self._max_consecutive}"
                )
                return True
            return False

        new_pos_np = np.array(new_position, dtype=np.float64)
        if ref_position is not None:
            last_pos = np.array(ref_position, dtype=np.float64)
        else:
            last_pos, _ = self.window[-1]
        safe_dt = max(dt, 0.01)

        # 1. Maximum-speed check
        # Distances are converted to TRUE ground metres before comparison with
        # the threshold; otherwise the threshold silently depends on mission latitude.
        distance = float(np.linalg.norm(new_pos_np - last_pos)) * self._ground_scale
        instantaneous_speed = distance / safe_dt

        is_speed_outlier = instantaneous_speed > self.max_speed_mps

        # 2. Statistical Z-score test (now based on SPEED, not distance)
        history = list(self.window)
        speeds = []
        for i in range(1, len(history)):
            p1, _ = history[i - 1]
            p2, hist_dt = history[i]
            dist = float(np.linalg.norm(p2 - p1)) * self._ground_scale
            speeds.append(dist / hist_dt)

        mean_speed = np.mean(speeds)
        std_speed = max(np.std(speeds), 1.0)

        z_score = abs(instantaneous_speed - mean_speed) / std_speed

        # 15.0 m/s - minimum speed delta for which Z-score is meaningful
        is_zscore_outlier = self._zscore_enabled and (
            z_score > self.threshold_std and abs(instantaneous_speed - mean_speed) > 15.0
        )

        if is_speed_outlier or is_zscore_outlier or is_maha_outlier:
            self._note_rejection(new_pos_np, pred_position)

            # Too many consecutive outliers — drone actually moved, reset window
            if self._streak_accept():
                logger.warning(
                    f"OUTLIER RESET: {self._consecutive_outliers} consecutive outliers — "
                    f"accepting new position. "
                    f"Position: ({new_pos_np[0]:.1f}, {new_pos_np[1]:.1f}), "
                    f"speed={instantaneous_speed:.1f}m/s"
                )
                self._accept_streak()
                return False  # Accept the new position

            if is_maha_outlier and not is_speed_outlier:
                logger.warning(
                    f"OUTLIER DETECTED (mahalanobis): d2={maha_d2:.2f} > {self._chi2_threshold:.2f} | "
                    f"speed={instantaneous_speed:.1f}m/s, distance={distance:.1f}m, dt={safe_dt:.3f}s, "
                    f"consecutive={self._consecutive_outliers}/{self._max_consecutive}"
                )
            elif is_speed_outlier:
                logger.warning(
                    f"OUTLIER DETECTED (speed): {instantaneous_speed:.1f} m/s > {self.max_speed_mps} m/s | "
                    f"distance={distance:.1f}m, dt={safe_dt:.3f}s, "
                    f"consecutive={self._consecutive_outliers}/{self._max_consecutive}"
                )
            else:
                logger.warning(
                    f"OUTLIER DETECTED (z-score): z={z_score:.2f} > {self.threshold_std} | "
                    f"speed={instantaneous_speed:.1f}m/s, mean_speed={mean_speed:.1f}m/s, std={std_speed:.1f}m/s, "
                    f"distance={distance:.1f}m, dt={safe_dt:.3f}s, "
                    f"consecutive={self._consecutive_outliers}/{self._max_consecutive}"
                )
            return True

        self._consecutive_outliers = 0
        self._streak_offsets.clear()
        return False


# ================================================================================
# File: src\tracking\smoother.py
# ================================================================================
"""Sliding-window back-end smoother for the live trajectory (RESEARCH 3.1).

Architecture (docs/RESEARCH_INTEGRATION_PLAN.md §3.1, design record in
.agents/SMOOTHER_DESIGN.md):

- Front-end (TrajectoryFilter KF + OutlierDetector) stays unchanged and keeps
  producing the per-frame output.
- This back-end maintains a sliding window of keyframe nodes (2D metric
  positions). Every H-based keyframe fix enters the window — including fixes
  the front-end rejected as outliers. Robust (Huber) IRLS weighting arbitrates
  instead of the front-end's binary accept/reject: a wrong fix gets a
  suppressed weight, a run of consistent "outliers" (real relocation, Z-score
  false positives during maneuvers) regains influence naturally.
- Inter-node edges are relative odometry derived from the optical-flow track
  (metric OF positions are anchored at the last accepted keyframe's H, so the
  difference of two OF samples is a fix-independent relative measurement).
- The solved window periodically corrects the KF via a position shift
  (TrajectoryFilter.shift): the correction is the difference between the
  smoothed and the KF estimate at the newest node.

Deliberate deviations from the plan text (rationale in the design note):

- Dedicated 2D linear solver instead of reusing the 5-DoF PoseGraphOptimizer.
  The live problem is linear in positions; Huber-IRLS over two per-axis SPD
  systems solves a 100-node window in well under a millisecond with plain
  numpy. The 5-DoF optimizer's residual contract (5E+N+5A) is calibration
  infrastructure with no per-anchor robust loss; wiring live usage into it
  would couple two hot paths for no numerical benefit.
- Synchronous solve on the keyframe cadence instead of an async thread. The
  async design existed to hide scipy 5-DoF solve latency; a sub-millisecond
  solve does not need hiding, and staying on the worker thread removes every
  lock/queue hazard around the shared KF state.

The problem solved per window (positions p_i, i = 0..N-1):

    sum_i  w_i * ||p_i - z_i||^2          (fixes; w_i Huber-reweighted, IRLS)
  + sum_e  w_e * ||p_j - p_i - d_e||^2    (odometry edges; quadratic, or
                                          Huber-IRLS when odom_huber_k > 0)
  + entry prior on the oldest node        (carries marginalized info forward)

x and y decouple into two SPD N x N systems sharing the same matrix.
"""

from dataclasses import dataclass

import numpy as np

from src.utils.logging_utils import get_logger

logger = get_logger(__name__)

# OF samples older than this (relative to the new node's time) are considered
# stale and produce no odometry edge. 0.5 s covers any realistic keyframe
# cadence (worker default: 5 frames at 30 fps = 0.17 s).
_OF_STALE_SEC = 0.5

# Floors mirroring front-end conventions (Localizer clips confidence at 0.25
# for the KF noise scale; OF quality below 0.2 is de facto garbage).
_CONF_FLOOR = 0.25
_QUALITY_FLOOR = 0.2


@dataclass
class _Node:
    uid: int
    t: float  # window-internal time of the keyframe [s]
    z: np.ndarray  # raw metric fix (2,)
    sigma: float  # fix sigma [m]
    accepted: bool  # front-end verdict
    kf_xy: np.ndarray | None  # front-end KF output at this node (accepted only)
    # OF-track position at this node's time, recorded at ingestion (used as
    # the edge start when this node is rejected — its own fix is untrusted).
    of_boundary: np.ndarray | None = None
    prior: tuple[np.ndarray, float] | None = None  # entry prior (xy, sigma)


@dataclass
class _Edge:
    a: int  # uid of the older node
    b: int  # uid of the newer node
    delta: np.ndarray  # measured p_b - p_a (2,)
    weight: float  # 1 / sigma^2


@dataclass
class _OfTrack:
    """OF samples of the current inter-keyframe interval (metric coords,
    anchored at the last accepted keyframe's homography). Survives rejected
    keyframes — the anchor only changes on acceptance."""

    prev: tuple[float, np.ndarray] | None = None  # (t, xy) — one before last
    last: tuple[float, np.ndarray] | None = None  # (t, xy) — latest sample
    q_min: float = 1.0
    n: int = 0

    def push(self, t: float, xy: np.ndarray, quality: float) -> None:
        self.prev = self.last
        self.last = (t, xy)
        self.q_min = min(self.q_min, quality)
        self.n += 1

    def clear(self) -> None:
        self.prev = None
        self.last = None
        self.q_min = 1.0
        self.n = 0

    def value_at(self, t: float) -> np.ndarray | None:
        """OF-track position extrapolated forward to time t (linear from the
        last two samples; falls back to the last sample; None if the track is
        empty or its newest sample is stale relative to t)."""
        if self.last is None:
            return None
        t_last, xy_last = self.last
        if t - t_last > _OF_STALE_SEC:
            return None
        if self.prev is not None:
            t_prev, xy_prev = self.prev
            dt = t_last - t_prev
            if dt > 1e-6:
                v = (xy_last - xy_prev) / dt
                return xy_last + v * (t - t_last)
        return xy_last.copy()


class SlidingWindowSmoother:
    """Robust sliding-window smoother over live keyframe fixes + OF odometry.

    Numpy-only, synchronous, deterministic. All inputs and outputs are in the
    metric coordinate frame of the active calibration source; the window is
    reset whenever the source changes (metric frames of different sources are
    not commensurable).
    """

    def __init__(
        self,
        window: int = 60,
        huber_k: float = 1.2,
        fix_sigma_base_m: float = 5.0,
        odom_sigma_base_m: float = 3.0,
        max_correction_m: float = 50.0,
        entry_prior_sigma_m: float = 15.0,
        irls_iterations: int = 4,
        correction_lag: int = 10,
        deadband_m: float = 2.0,
        gain: float = 0.25,
        max_step_m: float = 3.0,
        odom_huber_k: float = 0.0,
    ) -> None:
        self.window = max(int(window), 2)
        # Sanitise user-supplied parameters (live incident 2026-07-18:
        # huber_k=-0.8 in user_config made weights for ALL fixes negative —
        # the system ceased to be SPD, solution and servo steps became garbage).
        self.huber_k = self._sane("huber_k", huber_k, 0.1)
        self.fix_sigma_base_m = self._sane("fix_sigma_base_m", fix_sigma_base_m, 0.1)
        self.odom_sigma_base_m = self._sane("odom_sigma_base_m", odom_sigma_base_m, 0.1)
        self.max_correction_m = self._sane("max_correction_m", max_correction_m, 0.1)
        self.entry_prior_sigma_m = self._sane("entry_prior_sigma_m", entry_prior_sigma_m, 0.1)
        self.irls_iterations = max(int(irls_iterations), 1)
        # Fixed-lag servo (v2): correction is computed on the node at lag depth —
        # the window head is not yet refined by future evidence
        # (smoothed[head] ≈ raw fix, and correcting on it un-filtered the Kalman
        # — the trajectory was jerking towards raw fixes).
        self.correction_lag = max(int(correction_lag), 1)
        self.deadband_m = self._sane("deadband_m", deadband_m, 0.0)
        self.gain = min(self._sane("gain", gain, 0.01), 1.0)
        self.max_step_m = self._sane("max_step_m", max_step_m, 0.01)
        # Robust odometry (flag; 0 = legacy quadratic edges). A collapsed OF
        # track (LK lock lost on repetitive farmland, cloud, water) produces an
        # edge that contradicts the fixes; quadratic edges pass that error into
        # the window at full weight. Huber on the normalized edge residual
        # (|p_b - p_a - d| / sigma_e) suppresses it the same way fixes are.
        k_odom = float(odom_huber_k)
        if not np.isfinite(k_odom) or k_odom <= 0.0:
            self.odom_huber_k = 0.0
        else:
            self.odom_huber_k = max(k_odom, 0.1)

        self._nodes: list[_Node] = []
        self._edges: list[_Edge] = []
        self._of = _OfTrack()
        self._uid_seq = 0
        self._source_id: str | None = None
        # Two clocks accumulating the worker's video-time deltas:
        # _t_last_node — previous keyframe (accepted or rejected; KF dt
        # semantics), _t_last_success — last successful localization event
        # (accepted keyframe or OF sample; OF dt semantics).
        self._t_last_success = 0.0
        self._t_last_node = 0.0
        self._last_solution: dict[int, np.ndarray] = {}
        self._last_fix_weights: dict[int, float] = {}
        self._last_edge_weights: list[float] = []

        logger.info(
            f"SlidingWindowSmoother: window={self.window}, huber_k={self.huber_k}, "
            f"fix_sigma={self.fix_sigma_base_m}m, odom_sigma={self.odom_sigma_base_m}m, "
            f"odom_huber_k={self.odom_huber_k or 'off'}"
        )

    @staticmethod
    def _sane(name: str, value, floor: float) -> float:
        """Clamps a user config parameter from below with an explicit warning."""
        v = float(value)
        if not np.isfinite(v) or v < floor:
            logger.warning(f"Smoother config: {name}={value!r} invalid — clamping to {floor}")
            return float(floor)
        return v

    # ── ingestion ────────────────────────────────────────────────────────────

    def reset(self) -> None:
        self._nodes.clear()
        self._edges.clear()
        self._of.clear()
        self._source_id = None
        self._t_last_success = 0.0
        self._t_last_node = 0.0
        self._last_solution.clear()
        self._last_fix_weights.clear()
        self._last_edge_weights = []

    def note_of(self, metric_xy, dt: float, quality: float | None = None) -> None:
        """Register a successful optical-flow localization (raw metric point).

        dt follows the worker semantics: time since the last successful
        localization (previous OF frame or the anchoring keyframe).
        """
        if not self._nodes:
            return  # OF before any keyframe fix has no anchor in the window
        t = self._t_last_success + max(float(dt), 1e-3)
        self._t_last_success = t
        if quality is None:
            q = 0.7  # mirrors the front-end's default OF confidence
        else:
            q = max(float(quality), _QUALITY_FLOOR)
        self._of.push(t, np.asarray(metric_xy, dtype=np.float64).reshape(2), q)

    def add_fix(
        self,
        metric_xy,
        dt: float,
        confidence: float,
        source_id: str | None = None,
        accepted: bool = True,
        kf_xy=None,
    ) -> np.ndarray | None:
        """Ingest a keyframe fix, solve the window, return a KF correction.

        dt — time since the previous keyframe (worker semantics, rejected
        keyframes included). Returns the (dx, dy) shift to apply to the
        front-end KF, or None (window too small / node not accepted / solve
        skipped).
        """
        if source_id != self._source_id:
            if self._nodes:
                logger.info(
                    f"Smoother window reset: source change {self._source_id!r} -> {source_id!r}"
                )
            self.reset()
            self._source_id = source_id

        t_node = self._t_last_node + max(float(dt), 1e-3)
        z = np.asarray(metric_xy, dtype=np.float64).reshape(2)
        sigma = self.fix_sigma_base_m / max(float(confidence), _CONF_FLOOR)

        # OF-track position at this node's time — recorded NOW, while the
        # track state is contemporary (extrapolating backward later from newer
        # samples would be invalid).
        of_boundary = self._of.value_at(t_node)

        node = _Node(
            uid=self._uid_seq,
            t=t_node,
            z=z,
            sigma=sigma,
            accepted=bool(accepted),
            kf_xy=None if kf_xy is None else np.asarray(kf_xy, dtype=np.float64).reshape(2),
            of_boundary=of_boundary,
        )
        self._uid_seq += 1

        # Odometry edge from the previous node: OF-track displacement between
        # the two node times. Both boundary samples are anchored at the same
        # accepted keyframe's homography, so their difference is a
        # fix-independent relative measurement. An accepted previous node IS
        # the track's origin — its raw fix is the boundary sample.
        if self._nodes and of_boundary is not None:
            prev = self._nodes[-1]
            start = prev.z if prev.accepted else prev.of_boundary
            if start is not None:
                w = 1.0 / (self.odom_sigma_base_m / self._of.q_min) ** 2
                self._edges.append(
                    _Edge(a=prev.uid, b=node.uid, delta=of_boundary - start, weight=w)
                )

        self._nodes.append(node)
        self._t_last_node = t_node
        if accepted:
            self._t_last_success = t_node
            self._of.clear()  # the OF track re-anchors at this keyframe

        self._slide()
        solution = self.solve()

        if solution is None or not accepted or node.kf_xy is None:
            return None

        step = self._servo_step(solution)
        if step is not None:
            # Contract: the returned step is considered ALREADY applied by the
            # caller (localizer unconditionally shifts trajectory_filter). Rebase
            # the stored kf_xy values into the shifted frame — otherwise the lag
            # difference would count the same offset lag more times and servo would overshoot.
            for nd in self._nodes:
                if nd.kf_xy is not None:
                    nd.kf_xy = nd.kf_xy + step
        return step

    def _servo_step(self, solution: np.ndarray) -> np.ndarray | None:
        """Fixed-lag servo correction step or None.
        Difference smoothed - KF is taken at a node with depth >= correction_lag
        (where both estimates have settled — difference measures systematic
        drift, not per-fix noise). Then deadband (do not twitch KF in
        nominal flight), gain, and step limit (smooth convergence
        instead of teleportation; convergence is geometric thanks to kf_xy rebase).
        """
        lag = self.correction_lag
        if len(self._nodes) <= lag:
            return None
        for idx in range(len(self._nodes) - 1 - lag, -1, -1):
            ref = self._nodes[idx]
            if ref.kf_xy is not None:
                break
        else:
            return None  # no accepted node in the lag zone

        corr = solution[idx] - ref.kf_xy
        norm = float(np.linalg.norm(corr))
        if norm > self.max_correction_m:
            logger.warning(
                f"Smoother drift estimate clamped: {norm:.1f} m -> {self.max_correction_m} m"
            )
            corr = corr * (self.max_correction_m / norm)
            norm = self.max_correction_m
        if norm < self.deadband_m:
            return None

        step = corr * self.gain
        step_norm = float(np.linalg.norm(step))
        if step_norm > self.max_step_m:
            step = step * (self.max_step_m / step_norm)
        logger.debug(
            f"Smoother servo: drift {norm:.2f} m at lag {lag}, "
            f"step {float(np.linalg.norm(step)):.2f} m"
        )
        return step

    # ── window maintenance ───────────────────────────────────────────────────

    def _slide(self) -> None:
        while len(self._nodes) > self.window:
            dropped = self._nodes.pop(0)
            self._edges = [e for e in self._edges if e.a != dropped.uid and e.b != dropped.uid]
            # Entry prior: the new head keeps its last smoothed estimate as a
            # weak unary factor — cheap stand-in for proper marginalization,
            # prevents the window head from floating when old fixes leave.
            head = self._nodes[0]
            smoothed = self._last_solution.get(head.uid)
            if smoothed is not None:
                head.prior = (smoothed.copy(), self.entry_prior_sigma_m)

    # ── solver ───────────────────────────────────────────────────────────────

    def solve(self) -> np.ndarray | None:
        """Huber-IRLS solve of the current window. Returns (N, 2) smoothed
        positions in node order, or None if the window is empty/degenerate."""
        n = len(self._nodes)
        if n == 0:
            return None

        uid_to_idx = {node.uid: i for i, node in enumerate(self._nodes)}
        z = np.stack([node.z for node in self._nodes])  # (n, 2)
        sig = np.array([node.sigma for node in self._nodes])  # (n,)
        w_fix_base = 1.0 / np.square(sig)

        e_a = np.array([uid_to_idx[e.a] for e in self._edges], dtype=np.int64)
        e_b = np.array([uid_to_idx[e.b] for e in self._edges], dtype=np.int64)
        e_d = np.stack([e.delta for e in self._edges]) if self._edges else np.zeros((0, 2))
        e_w = np.array([e.weight for e in self._edges], dtype=np.float64)

        diag = np.arange(n)
        hw = np.ones(n, dtype=np.float64)  # Huber weights on fixes
        hw_e = np.ones(len(e_w), dtype=np.float64)  # Huber weights on odometry
        e_sig = 1.0 / np.sqrt(np.maximum(e_w, 1e-300))
        p = z.copy()

        for _ in range(self.irls_iterations):
            w_fix = w_fix_base * hw
            A = np.zeros((n, n), dtype=np.float64)
            b = np.zeros((n, 2), dtype=np.float64)

            A[diag, diag] += w_fix
            b += w_fix[:, None] * z

            for i, node in enumerate(self._nodes):
                if node.prior is not None:
                    pw = 1.0 / node.prior[1] ** 2
                    A[i, i] += pw
                    b[i] += pw * node.prior[0]

            if len(self._edges):
                ew = e_w * hw_e
                np.add.at(A, (e_a, e_a), ew)
                np.add.at(A, (e_b, e_b), ew)
                np.add.at(A, (e_a, e_b), -ew)
                np.add.at(A, (e_b, e_a), -ew)
                np.subtract.at(b, e_a, ew[:, None] * e_d)
                np.add.at(b, e_b, ew[:, None] * e_d)

            try:
                p = np.linalg.solve(A, b)
            except np.linalg.LinAlgError:
                logger.warning("Smoother solve failed (singular system) — skipping")
                return None

            u = np.linalg.norm(p - z, axis=1) / sig
            hw = np.where(u <= self.huber_k, 1.0, self.huber_k / np.maximum(u, 1e-12))
            if self.odom_huber_k > 0.0 and len(self._edges):
                r_e = np.linalg.norm(p[e_b] - p[e_a] - e_d, axis=1) / e_sig
                k = self.odom_huber_k
                hw_e = np.where(r_e <= k, 1.0, k / np.maximum(r_e, 1e-12))

        self._last_solution = {node.uid: p[i].copy() for i, node in enumerate(self._nodes)}
        self._last_fix_weights = {node.uid: float(hw[i]) for i, node in enumerate(self._nodes)}
        self._last_edge_weights = [float(w) for w in hw_e]
        return p

    # ── introspection (tests / telemetry) ────────────────────────────────────

    @property
    def num_nodes(self) -> int:
        return len(self._nodes)

    @property
    def num_edges(self) -> int:
        return len(self._edges)

    @property
    def last_fix_weights(self) -> dict[int, float]:
        """uid -> final Huber weight of the fix (1.0 = fully trusted)."""
        return dict(self._last_fix_weights)

    @property
    def last_edge_weights(self) -> list[float]:
        """Final Huber weights of odometry edges in edge order (1.0 = trusted;
        all 1.0 when odom_huber_k is off)."""
        return list(self._last_edge_weights)


